mapper.select:
	select * from ww_task_lean where 1=1
	
		and job_id = #{jobId}
	
	
		and task_id = #{taskId}
	
	
		and lean_task_id = #{leanTaskId}
	
    
	
		and (lean_job_id is null or lean_job_id=job_id)
	
	
		order by task_id

mapper.update:
    	update ww_task_lean
    	set lean_job_id = #{leanJobId,jdbcType=VARCHAR}
    	where job_id = #{jobId}
			and task_id = #{taskId}
			and lean_task_id = #{leanTaskId}

mapper.delete:
