mapper.select:
select a.lean_task_id, a.type, IF(t.use_job_dimension = '0',(select count(1) from ww_task_dimension td where td.job_id=a.job_id and td.task_id=a.lean_task_id), 1) includeDimension                                                  
from (
  select tl.job_id,tl.lean_task_id, '1' type from ww_task_lean tl where tl.job_id=#{jobId} and tl.task_id=#{taskId}
  union all
  select distinct tsl.job_id,tsl.lean_task_id, '2' type from ww_task_special_lean tsl where tsl.job_id=#{jobId} and tsl.task_id=#{taskId}
) a, ww_task t
where a.job_id = t.job_id and a.lean_task_id = t.task_id
order by a.lean_task_id

select a.lean_task_id, a.type, decode(t.use_job_dimension,'0',(select count(1) from ww_task_dimension td where td.job_id=a.job_id and td.task_id=a.lean_task_id),1) includeDimension                                                  
from (
  select tl.job_id,tl.lean_task_id, '1' type from ww_task_lean tl where tl.job_id=#{jobId} and tl.task_id=#{taskId}
  union all
  select distinct tsl.job_id,tsl.lean_task_id, '2' type from ww_task_special_lean tsl where tsl.job_id=#{jobId} and tsl.task_id=#{taskId}
) a, ww_task t
where a.job_id = t.job_id and a.lean_task_id = t.task_id
order by a.lean_task_id

select a.task_id, a.type, IF(t.use_job_dimension = '0',(select count(1) from ww_task_dimension td where td.job_id=a.job_id and td.task_id=a.task_id), 1) includeDimension                                                  
from (
  select tl.job_id,tl.task_id, '1' type from ww_task_lean tl where tl.job_id=#{jobId} and tl.lean_task_id=#{taskId}
  union all
  select distinct tsl.job_id,tsl.task_id, '2' type from ww_task_special_lean tsl where tsl.job_id=#{jobId} and tsl.lean_task_id=#{taskId}
) a, ww_task t
where a.job_id = t.job_id and a.task_id = t.task_id
order by a.task_id

select a.task_id, a.type, decode(t.use_job_dimension,'0',(select count(1) from ww_task_dimension td where td.job_id=a.job_id and td.task_id=a.task_id),1) includeDimension                                                  
from (
  select tl.job_id,tl.task_id, '1' type from ww_task_lean tl where tl.job_id=#{jobId} and tl.lean_task_id=#{taskId}
  union all
  select distinct tsl.job_id,tsl.task_id, '2' type from ww_task_special_lean tsl where tsl.job_id=#{jobId} and tsl.lean_task_id=#{taskId}
) a, ww_task t
where a.job_id = t.job_id and a.task_id = t.task_id
order by a.task_id
